// Search all three-toggle configurations at the second possible signature
// distance, allowing an additional kernel word generated by up to two stars.
#include "star_board.hpp"
#include "kernel_triples.hpp"
#include <algorithm>
#include <bit>
#include <cstdlib>
#include <iostream>
#include <numeric>
using namespace std;

struct Shape { array<int,3> sites; array<uint64_t,8> cover{}; };
struct Shapes {
    vector<Shape> all;
    vector<int> indices;
    array<vector<int>,512> covers_origin_and;
    explicit Shapes(const Board& board){
        for(int centre=0;centre<board.n;centre++){
            vector<int> near;
            for(int v=0;v<board.n;v++)
                if(v!=centre&&popcount(unsigned(centre^v))<=2) near.push_back(v);
            for(int j=0;j<int(near.size());j++) for(int i=0;i<j;i++){
                int a=near[i],b=near[j];
                // A chain has a unique middle. For a triangle use its least site.
                if(popcount(unsigned(a^b))<=2 && min(a,b)<centre)continue;
                Shape sh{{centre,a,b}};
                for(int v:sh.sites)for(int k=0;k<=board.d;k++){
                    int z=board.ball[v][k];sh.cover[z>>6]|=uint64_t(1)<<(z&63);
                }
                if(sh.cover[0]&1){
                    for(int j=0;j<(board.n+63)/64;j++){
                        auto bits=sh.cover[j];
                        while(bits){
                            int z=64*j+countr_zero(bits);bits&=bits-1;
                            covers_origin_and[z].push_back(int(all.size()));
                        }
                    }
                }
                all.push_back(sh);
            }
        }
        indices.resize(all.size());iota(indices.begin(),indices.end(),0);
    }
};

int main(){
    int d,target,limit,records;
    if(!(cin>>d>>target>>limit>>records)||d<2||d>9||limit<0||limit>3)return 2;
    Shapes shapes{Board(d)};
    for(int index=0;index<records;index++){
        Board board(d);int count;cin>>count;
        for(int i=0,v;i<count;i++){cin>>v;board.toggle(v);}
        array<long long,4> classes{},examined{},models{},solutions{};
        vector<int> first;array<int,6> change{-1,-1,-1,-1,-1,-1};
        auto test=[&](int a,int b,int k,int c=-1){
            ++classes[k];
            const int gap=abs(board.size-target);
            if((gap!=1&&gap!=3)||board.bad>3*(d+1)||abs(board.tips-2)>3*(d+1))return;
            array<int,30> bad{};int m=0,origin=0;
            const vector<int>* options=&shapes.indices;
            for(int j=0;j<(board.n+63)/64;j++){
                auto bits=board.bad_sites[j];
                while(bits){
                    int v=j*64+countr_zero(bits);bits&=bits-1;
                    if(!m)origin=v;
                    int x=v^origin;
                    const auto& bucket=shapes.covers_origin_and[x];
                    if(bucket.empty())return;
                    if(bucket.size()<options->size())options=&bucket;
                    bad[m++]=x;
                }
            }
            for(int id:*options){
                const Shape& s=shapes.all[id];
                bool covered=true;
                for(int i=0;i<m;i++)if(!(s.cover[bad[i]>>6]>>(bad[i]&63)&1)){covered=false;break;}
                if(!covered)continue;
                int x=s.sites[0]^origin,y=s.sites[1]^origin,z=s.sites[2]^origin;
                if(board.size+3-2*(board.used[x]+board.used[y]+board.used[z])!=target)continue;
                ++examined[k];
                board.toggle(x);board.toggle(y);board.toggle(z);
                if(!board.bad&&board.tips==2){
                    ++models[k];auto q=board.path();
                    if(!q.empty()){
                        ++solutions[k];if(first.empty()){first=q;change={x,y,z,a,b,c};}
                    }
                }
                board.toggle(z);board.toggle(y);board.toggle(x);
            }
        };
        test(-1,-1,0);
        if(limit>=1)for(int a=0;a<board.n;a++){
            board.star(a);test(a,-1,1);
            if(limit>=2)for(int b=a+1;b<board.n;b++){
                board.star(b);test(a,b,2);board.star(b);
            }
            board.star(a);
        }
        if(limit==3)kernel_triples(board,[&](int a,int b,int c){test(a,b,3,c);});
        cout<<index<<' '<<shapes.all.size();
        int width=limit==3?4:3;
        for(auto arr:{classes,examined,models,solutions})for(int j=0;j<width;j++)cout<<' '<<arr[j];
        for(int j=0;j<width+2;j++)cout<<' '<<change[j];
        cout<<' '<<first.size();for(auto v:first)cout<<' '<<v;cout<<endl;
    }
}
